var _testExtendedTestdataLoggingRapidastJob_rapidastYaml = []byte(`kind: Template
apiVersion: template.openshift.io/v1
metadata:
  name: rapidast-job-template
objects:
- apiVersion: batch/v1
  kind: Job
  metadata:
    name: ${NAME}
  spec:
    backoffLimit: 0
    completionMode: NonIndexed
    completions: 1
    parallelism: 1
    selector:
      matchLabels:
        job-name: ${NAME}
    suspend: false
    template:
      metadata:
        labels:
          job-name: ${NAME}
        name: rapidast-job
      spec:
        containers:
        - command: ["/bin/sh"]
          args:
          - "-c"
          - | 
            export HOME=/home/rapidast 
            mkdir -p $HOME/.ZAP/policies 
            cp /opt/rapidast/config/customscan.policy $HOME/.ZAP/policies/custom-scan.policy 
            rapidast.py --config /opt/rapidast/config/rapidastconfig.yaml
            echo "--------------- show rapidash result -----------------"  
            find $HOME/results/ocptest -name zap-report.json -exec cat {} \;
            echo "--------------- rapidash result end -----------------"  
          image: quay.io/redhatproductsecurity/rapidast:latest
          workingDir: "/home/rapidast"
          imagePullPolicy: Always
          name: rapidast
          resources: {}
          securityContext: {}
          terminationMessagePath: /dev/termination-log
          terminationMessagePolicy: File
          volumeMounts:
          - mountPath: /opt/rapidast/config
            name: config-volume
          - mountPath: /home/rapidast
            name: work-volume
        dnsPolicy: ClusterFirst
        restartPolicy: Never
        schedulerName: default-scheduler
        securityContext: {}
        terminationGracePeriodSeconds: 30
        nodeSelector:
          kubernetes.io/os: linux
          kubernetes.io/arch: amd64
        volumes:
        - configMap:
            defaultMode: 420
            name: ${NAME}
          name: config-volume
        - name: work-volume
          emptyDir:
            sizeLimit: 10Mi
parameters:
- name: NAME
  value: rapidast-job
`)

