var _testExtendedTestdataOapCertmanagerRapidastPodYaml = []byte(`# DO NOT MODIFY DIRECTLY
apiVersion: template.openshift.io/v1
kind: Template
metadata:
  name: rapidast-pod-template
objects:
  - apiVersion: v1
    kind: PersistentVolumeClaim
    metadata:
      name: "${PVC_NAME}"
    spec:
      accessModes:
        - ReadWriteOnce
      resources:
        requests:
          storage: 100M
  - apiVersion: v1
    kind: Pod
    metadata:
      name: "${POD_NAME}"
    spec:
      serviceAccount: "${SA_NAME}"
      volumes:
        - name: config-volume
          configMap:
            name: "${CONFIGMAP_NAME}"
        - name: results-volume
          persistentVolumeClaim:
            claimName: "${PVC_NAME}"
      containers:
        - name: rapidast
          image: quay.io/redhatproductsecurity/rapidast:latest
          imagePullPolicy: IfNotPresent
          command:
            - "sh"
            - "-c"
            - >
              rapidast.py --config /helm/config/rapidastconfig.yaml &&
              find /opt/rapidast/results -name zap-report.json -exec cat {} \;
          securityContext:
            privileged: true
          volumeMounts:
            - name: config-volume
              mountPath: "/helm/config"
            - name: results-volume
              mountPath: "/opt/rapidast/results"
      restartPolicy: Never
parameters:
  - name: POD_NAME
  - name: SA_NAME
  - name: CONFIGMAP_NAME
  - name: PVC_NAME
`)

